sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartEnd = null;

    $scope.anoSelecionadoEnd = "";
    $scope.exibirGraficoEnd = false;

    var coresEnd = {
        apurado: '#a7b9e8',
        meta: '#4b77bf'
    };

    /**
     * Função para carregar os dados do servidor com filtro de ano
     */
    function carregarDadosEndFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoEnd || ""
        };
        $scope.server.get(filtros).then(function(response) {
            var dados = response.data.dadosGraficoEnd || [];
            var anosDisponiveis = response.data.anos || [];

            // --- MUDANÇA AQUI ---
            // Substituímos o $timeout simples pela nossa verificação de segurança
            verificarBibliotecaChart(function() {
                montarGraficoEnd(dados, anosDisponiveis);
            });
        });
    }

    /**
     * --- NOVA FUNÇÃO DE SEGURANÇA ---
     * Verifica se a biblioteca Chart.js já foi carregada.
     */
    function verificarBibliotecaChart(callbackSucesso) {
        if (typeof Chart !== 'undefined') {
            callbackSucesso();
        } else {
            // Se ainda não carregou, espera 500ms e tenta de novo
            $timeout(function() {
                verificarBibliotecaChart(callbackSucesso);
            }, 500);
        }
    }

    // Escuta o evento de mudança de ano disparado pelo seu filtro
    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoEnd = ano;
        carregarDadosEndFiltrado();
    });

    // Chamada inicial
    carregarDadosEndFiltrado();

    function montarGraficoEnd(listaDados, anosDisponiveis) {

        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });
        // Ordena os anos de forma crescente (Ex: 2022, 2023, 2024)
        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        if (anosPresentes.length === 0) {
            if (chartEnd) {
                chartEnd.destroy();
                chartEnd = null;
            }
            $scope.exibirGraficoEnd = false;
            $scope.$applyAsync(); 
            return;
        }
        $scope.exibirGraficoEnd = true;
        $scope.$applyAsync(); 

        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.apurado) : null;
        });
        var dadosMeta = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.meta) : null;
        });
        var desiredType = (anosPresentes.length === 1) ? 'bar' : 'line';

        var datasets = [{
            label: 'Valor Apurado',
            data: dadosApurado,
            fill: false,
            tension: 0.1
        }, {
            label: 'Meta',
            data: dadosMeta,
            fill: false,
            tension: 0.1
        }];

        if (desiredType === 'line') {
            datasets[0].borderColor = coresEnd.apurado;
            datasets[0].backgroundColor = coresEnd.apurado; // Removida a transparência para opaco
            datasets[0].borderWidth = 4;
            datasets[0].pointStyle = 'circle';
            datasets[0].pointRadius = 10; // Aumentado o tamanho do círculo (ponto) no gráfico
            datasets[1].borderColor = coresEnd.meta;
            datasets[1].backgroundColor = coresEnd.meta; // Removida a transparência para opaco
            datasets[1].borderWidth = 4;
            datasets[1].pointStyle = 'circle';
            datasets[1].pointRadius = 10; // Aumentado o tamanho do círculo (ponto) no gráfico
        } else { // bar
            datasets[0].backgroundColor = coresEnd.apurado;
            datasets[0].borderColor = coresEnd.apurado;
            datasets[0].borderWidth = 1;
            datasets[1].backgroundColor = coresEnd.meta;
            datasets[1].borderColor = coresEnd.meta;
            datasets[1].borderWidth = 1;
        }

        // Set point styles for legend
        datasets[0].pointStyle = 'rect';
        datasets[0].pointBackgroundColor = coresEnd.apurado;
        datasets[0].pointBorderColor = coresEnd.apurado;
        datasets[0].pointBorderWidth = 0;
        datasets[1].pointStyle = 'rect';
        datasets[1].pointBackgroundColor = coresEnd.meta;
        datasets[1].pointBorderColor = coresEnd.meta;
        datasets[1].pointBorderWidth = 0;

        // --- SEGURANÇA ADICIONAL ---
        // Verifica se o elemento existe no HTML antes de tentar desenhar
        var canvasElement = document.getElementById('graficoEndLinha');
        if (!canvasElement) return;

        var ctx = canvasElement.getContext('2d');

        if (chartEnd) {
            if (chartEnd.config.type !== desiredType) {
                chartEnd.destroy();
                chartEnd = null;
            } else {
                // APLICA O MÉTODO UPDATE PARA TRANSIÇÃO SUAVE
                chartEnd.data.labels = anosPresentes;
                chartEnd.data.datasets[0].data = dadosApurado;
                chartEnd.data.datasets[1].data = dadosMeta;
                chartEnd.update();
                return;
            }
        }

        // Criação inicial do gráfico ou recriação se tipo mudou
        chartEnd = new Chart(ctx, {
            type: desiredType,
            data: {
                labels: anosPresentes,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: {
                    duration: 700,
                    easing: 'easeInOutQuad'
                },
                scales: {
                    x: {
                        display: true,
                        title: {
                            display: false
                        },
                        offset: true,
                        grid: {
                            offset: true
                        },
                        ticks: {
                            color: '#0E2B69',
                            font: {
                                size: 16,
                                weight: 800,
                                family: 'Roboto Flex, sans-serif',
                                lineHeight: 1.8
                            },
                            padding: 6,
                            maxRotation: 0,
                            autoSkip: false
                        }
                    },
                    y: {
                        display: true,
                        position: 'right',
                        min: 0,
                        max: 100,
                        ticks: {
                            callback: function(value) {
                                return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                            },
                            color: '#0E2B69',
                            font: {
                                size: 14,
                                family: 'Roboto Flex, sans-serif'
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top',
                        labels: {
                            usePointStyle: true
                        }
                    },
                    tooltip: {
                        enabled: true,
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + context.raw.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                            }
                        }
                    },
                    datalabels: {
                        anchor: 'end',
                        align: 'top',
                        formatter: function(value) {
                            if (value === null) return '';
                            return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                        },
                        color: '#000',
                        font: {
                            weight: 'bold'
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    data.dadosGraficoEnd = [];
    data.anos = [];
    // O ano é lido do input enviado pelo Client Script
    var anoFiltro = input.ano || "";

    // --- 1. Busca e Popula os Anos Disponíveis (para o filtro) ---
    var grAnos = new GlideAggregate('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
    grAnos.addAggregate('COUNT');
    grAnos.groupBy('u_ano');
    grAnos.orderBy('u_ano');
    grAnos.query();

    while (grAnos.next()) {
        data.anos.push(grAnos.getValue('u_ano').toString());
    }
    data.anos = Array.from(new Set(data.anos));
    data.anos.sort();
    // --- 2. Busca os Dados ---
    var grEnd = new GlideRecord('x_sded9_portal_t_0_programa_de_ajuste_fiscal');

    // ** LÓGICA DE FILTRO ATUALIZADA **
    if (anoFiltro !== "" && anoFiltro.toLowerCase() !== "todos") {
        // Se um ano específico for selecionado, filtra por ele (Ano ÚNICO)
        grEnd.addQuery('u_ano', anoFiltro);
    }
    // Se 'anoFiltro' for "Todos" ou vazio, NENHUM filtro é aplicado aqui,
    // o que fará com que o grEnd busque todos os dados disponíveis.

    // Ordena
    grEnd.orderBy('u_ano');
    grEnd.query();
    var listaEnd = [];
    while (grEnd.next()) {
        var ano = grEnd.getValue('u_ano').toString();
        var apurado = grEnd.getValue('valor_apurado_endividamento') || '0';
        var meta = grEnd.getValue('meta_endividamento') || '0';

        listaEnd.push({
            ano: ano,
            apurado: apurado,
            meta: meta
        });
    }

    data.dadosGraficoEnd = listaEnd;
})();
